package com.bank.catalyst.plan;

import java.util.List;

// A tiny logical plan: scan a table, filter by account, project columns.
public class LogicalPlan {
    public String table;
    public String filterAccount;          // predicate
    public List<String> projectedColumns; // columns requested
    public boolean analyzed;
    public boolean predicatePushedDown;
    public boolean columnsPruned;

    public LogicalPlan(String table, String filterAccount, List<String> projectedColumns) {
        this.table = table;
        this.filterAccount = filterAccount;
        this.projectedColumns = projectedColumns;
    }
}
