package com.bank.catalyst.plan;

import java.util.Set;
import java.util.logging.Logger;

// Phase 2: resolve column names against the schema (catalog).
public class Analyzer {
    private static final Logger log = Logger.getLogger(Analyzer.class.getName());
    private final Set<String> schemaColumns;

    public Analyzer(Set<String> schemaColumns) {
        this.schemaColumns = schemaColumns;
    }

    public LogicalPlan analyze(LogicalPlan plan) {
        log.info("ANALYZE: resolving column names against schema");
        for (String c : plan.projectedColumns) {
            if (!schemaColumns.contains(c)) {
                throw new IllegalArgumentException("Unknown column: " + c);
            }
        }
        plan.analyzed = true;
        return plan;
    }
}
