package com.bank.catalyst.plan;

import java.util.logging.Logger;

// Phase 3: rule-based logical optimization.
public class Optimizer {
    private static final Logger log = Logger.getLogger(Optimizer.class.getName());

    public LogicalPlan optimize(LogicalPlan plan) {
        if (!plan.analyzed) throw new IllegalStateException("plan must be analyzed first");
        // Rule: predicate pushdown — push the account filter into the scan.
        if (plan.filterAccount != null) {
            plan.predicatePushedDown = true;
            log.info(() -> "RULE predicate pushdown: filter account="
                    + plan.filterAccount + " pushed into scan");
        }
        // Rule: column pruning — read only the projected columns.
        plan.columnsPruned = true;
        log.info(() -> "RULE column pruning: read only " + plan.projectedColumns);
        return plan;
    }
}
