package com.bank.catalyst.plan;

import com.bank.catalyst.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Phase 4: pick a physical plan + whole-stage codegen, then execute.
public class PhysicalPlanner {
    private static final Logger log = Logger.getLogger(PhysicalPlanner.class.getName());

    public List<BigDecimal> execute(LogicalPlan plan, List<Txn> rows) {
        log.info("PHYSICAL: whole-stage codegen fuses scan+filter+project into one loop");
        int rowsRead = 0, colsRead;
        colsRead = plan.columnsPruned ? plan.projectedColumns.size() : 4;

        List<BigDecimal> out = new ArrayList<>();
        for (Txn t : rows) {
            // Predicate pushdown: scan skips non-matching rows at the source.
            if (plan.predicatePushedDown && !t.getAccountId().equals(plan.filterAccount)) {
                continue; // not even materialized into the row count
            }
            rowsRead++;
            out.add(t.getAmount());
        }
        final int rr = rowsRead, cr = colsRead;
        log.info(() -> "EXECUTE: rows read=" + rr + " (of " + rows.size()
                + "), columns read=" + cr + " (of 4)");
        return out;
    }
}
