package com.bank.catalyst;

import com.bank.catalyst.model.Txn;
import com.bank.catalyst.plan.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class CatalystDemo {
    private static final Logger log = Logger.getLogger(CatalystDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new CatalystLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        List<Txn> rows = List.of(
            new Txn("SAV2001", new BigDecimal("1000"), "MUM", "UPI"),
            new Txn("CUR3001", new BigDecimal("500"), "DEL", "NEFT"),
            new Txn("SAV2001", new BigDecimal("3000"), "MUM", "IMPS"),
            new Txn("CUR3001", new BigDecimal("700"), "DEL", "UPI")
        );

        // Parsed logical plan: want amount for Rajesh's txns only.
        LogicalPlan plan = new LogicalPlan("transactions", "SAV2001", List.of("amount"));

        // Phase 2: analyze against schema.
        Set<String> schema = Set.of("accountId", "amount", "branch", "channel");
        plan = new Analyzer(schema).analyze(plan);

        // Phase 3: optimize (pushdown + pruning).
        plan = new Optimizer().optimize(plan);

        // Phase 4: physical plan + execute.
        List<BigDecimal> result = new PhysicalPlanner().execute(plan, rows);
        log.info(() -> "Rajesh amounts = " + result);
    }
}

